"use strict";

var _utilities = require("../../../utilities");
var _FlagsFilter = require("../FlagsFilter.utils");
describe('convertFlagsToFilterOptions', function () {
  it('returns empty when there are no flags', function () {
    expect((0, _FlagsFilter.convertFlagsToFilterOptions)(null)).toEqual([]);
  });
  it('should correctly convert flags to filter options', function () {
    var flags = [{
      id: '123',
      name: 'American'
    }];
    var options = [{
      id: '123',
      label: 'American'
    }];
    expect((0, _FlagsFilter.convertFlagsToFilterOptions)(flags)).toEqual(options);
  });
});
describe('prependFilterName', function () {
  it('should prepend', function () {
    var callback = jest.fn();
    (0, _FlagsFilter.prependFilterName)(callback)('test');
    expect(callback.mock.calls[0][0]).toEqual(_utilities.FILTER_NAMES.itemFlagIds);
    expect(callback.mock.calls[0][3]).toEqual('test');
  });
});